<script lang="ts">
  import type { TurnMetrics, ObservedRegion } from './agent-progress.js';
  interface Props {
    metrics?: TurnMetrics;
    regions?: readonly (ObservedRegion & { currentSource: boolean })[];
  }
  let { metrics, regions = [] }: Props = $props();
</script>

{#if metrics}<h4>Turn measurements</h4><p>{metrics.toolCalls} tool calls · {metrics.refusedCalls} refused · {metrics.recoveryAttempts} calls after refusal · {(metrics.elapsedMs/1000).toFixed(1)} s elapsed.</p>{#if metrics.partial}<p>Partial browser measurements; the server completion receipt was not received. Provider requests and token usage unavailable.</p>{:else}<p>{metrics.providerRequests} authoring model requests · {metrics.visionRequests} image requests. {metrics.firstEditMs===undefined?'No confirmed edit.':`First confirmed edit ${(metrics.firstEditMs/1000).toFixed(1)} s.`}</p><p>{metrics.usage?`Reported authoring usage: ${metrics.usage.inputTokens} input / ${metrics.usage.outputTokens} output tokens.`:'Token usage unavailable.'}</p>{/if}<p>{metrics.confirmedEdits??0} receipt-derived edits including cleanup.</p>{#if metrics.categories}<p>{metrics.categories.knowledge} knowledge reads · {metrics.categories.source} source reads · {metrics.categories.edit} edit calls · {metrics.categories.observe} observation calls.</p>{/if}{#if metrics.toolActiveMs!==undefined}<p>Settled tool durations summed: {(metrics.toolElapsedMs/1000).toFixed(1)} s; tool-active interval union: {(metrics.toolActiveMs/1000).toFixed(1)} s; outside-tool time: {((metrics.outsideToolMs??0)/1000).toFixed(1)} s.</p><p>Outside-tool time includes waiting, generation, transport and host overhead; exact provider latency is unavailable.</p>{/if}<p>Exact model steps and cost unavailable. Concurrent tool durations do not add up to wall time.</p>{/if}
          {#if regions.length}<h4>Observed regions</h4>{#each regions as region}<p>{region.cursor.revision} · {region.currentSource?"current source":"earlier source"} · {region.image.width}×{region.image.height} at ({region.image.offsetLeft}, {region.image.offsetTop}) within {region.image.sourceWidth}×{region.image.sourceHeight}; {region.preview.mode}; {region.capturedAt}.</p>{/each}<p>Only these captured regions were inspected. Current source does not establish current runtime/viewport freshness. Offscreen content and interactions remain unverified.</p>{/if}
